import itertools
import json

def solve_puzzle():
    houses = [1, 2, 3]  # left to right
    Names = ['Arnold', 'Eric', 'Peter']
    MusicGenre = ['pop', 'rock', 'classical']
    Children = ['Fred', 'Meredith', 'Bella']
    BookGenre = ['mystery', 'romance', 'science fiction']

    solutions = []

    for names in itertools.permutations(Names):
        # Clue 2: Peter is in the first house.
        if names[0] != 'Peter':
            continue

        for books in itertools.permutations(BookGenre):
            # Clue 5: Eric is the person who loves mystery books.
            try:
                pos_mystery = books.index('mystery')
            except ValueError:
                continue
            if names[pos_mystery] != 'Eric':
                continue

            for music in itertools.permutations(MusicGenre):
                # Clue 3: The person who loves mystery books is the person who loves classical music.
                if music[pos_mystery] != 'classical':
                    continue

                for children in itertools.permutations(Children):
                    # Helper: positions
                    pos = lambda arr, val: arr.index(val)

                    # Clue 1: The person whose child is Fred is directly left of the person who loves mystery books.
                    if not (pos(children, 'Fred') + 1 == pos_mystery):
                        continue

                    # Clue 4: The person who loves science fiction books is the parent of Meredith.
                    if pos(books, 'science fiction') != pos(children, 'Meredith'):
                        continue

                    # Clue 6: Rock music is somewhere to the right of romance books.
                    if not (pos(music, 'rock') > pos(books, 'romance')):
                        continue

                    # All constraints satisfied; record solution
                    rows = []
                    for h in houses:
                        i = h - 1
                        rows.append([
                            str(h),
                            names[i],
                            music[i],
                            children[i],
                            books[i]
                        ])
                    solutions.append(rows)

    # Choose the first solution found (expected to be unique)
    if not solutions:
        raise RuntimeError("No solution found for the given puzzle constraints.")
    result_rows = solutions[0]

    output = {
        "solution": {
            "header": ["House", "Name", "MusicGenre", "Children", "BookGenre"],
            "rows": result_rows
        }
    }
    print(json.dumps(output))


if __name__ == "__main__":
    solve_puzzle()
